(function() {
  const scope = document.currentScript.closest('.chapter-container') || document;

  // Elements
  const btnNoise = scope.querySelector('#btn-noise');
  const btnGeometry = scope.querySelector('#btn-geometry');
  const modal = scope.querySelector('#noise-modal');
  const closeBtn = modal.querySelector('.close-btn');
  const expansionText = scope.querySelector('#expansion-text');
  const noiseStatus = scope.querySelector('#noise-status');

  // State
  let isModalOpen = false;

  // Functions
  function openModal() {
    if (!modal) return;
    modal.setAttribute('aria-hidden', 'false');
    isModalOpen = true;
    // Focus trap could be added here for full a11y
    closeBtn.focus();
  }

  function closeModal() {
    if (!modal) return;
    modal.setAttribute('aria-hidden', 'true');
    isModalOpen = false;
    if (btnNoise) btnNoise.focus();
  }

  function toggleEquationExpansion() {
    if (!expansionText) return;
    const isExpanded = expansionText.style.opacity === '0';
    expansionText.style.transition = 'opacity 0.3s';
    expansionText.style.opacity = isExpanded ? '1' : '0';
    expansionText.textContent = isExpanded ? '= K_i - 2x_i x - 2y_i y + x^2 + y^2' : '';
  }

  // Event Listeners
  if (btnNoise) {
    btnNoise.addEventListener('click', function(e) {
      e.preventDefault();
      openModal();
      // In a real environment, this would trigger the source viewer via data-source
      console.log('Source request:', this.getAttribute('data-source'));
    });
  }

  if (btnGeometry) {
    btnGeometry.addEventListener('click', function(e) {
      e.preventDefault();
      toggleEquationExpansion();
      console.log('Source request:', this.getAttribute('data-source'));
    });
  }

  if (closeBtn) {
    closeBtn.addEventListener('click', closeModal);
  }

  // Close modal on outside click
  if (modal) {
    modal.addEventListener('click', function(e) {
      if (e.target === modal) {
        closeModal();
      }
    });
  }

  // Keyboard accessibility
  document.addEventListener('keydown', function(e) {
    if (isModalOpen && e.key === 'Escape') {
      closeModal();
    }
  });

  // Initialize
  if (expansionText) {
    expansionText.style.opacity = '1';
  }

  // Concept button handler (delegated)
  scope.addEventListener('click', function(e) {
    const conceptBtn = e.target.closest('[data-concept]');
    if (conceptBtn) {
      const conceptId = conceptBtn.getAttribute('data-concept');
      console.log('Concept request:', conceptId);
      // In real env, this would open concept viewer
    }
  });
})();
